import{d as p,C as s,o as g,c as d,a3 as t,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第三十章","description":"《正易心法》第三十章——二十四爻，求之八卦：384 爻中 360 为正爻配平年、24 为叠数配闰月；其数来自八纯卦上下相叠之重复，故闰数不只见于数，亦见于象。","frontmatter":{"title":"正易心法·第三十章","description":"《正易心法》第三十章——二十四爻，求之八卦：384 爻中 360 为正爻配平年、24 为叠数配闰月；其数来自八纯卦上下相叠之重复，故闰数不只见于数，亦见于象。","category":"guide","aliases":["正易心法第三十章","二十四爻求之八卦","叠数与闰数"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-30.md","filePath":"yijing/zheng-yi-xin-fa/chapter-30.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-30.md"},x=p({...c,setup(u){const i=[{id:"z30-01",label:"一、二十四爻之求",showLabel:!0,sentences:[["二十四爻，求之八卦。画纯为",{text:"叠",glossary:"die"},"，是为",{text:"闰数",glossary:"runshu"},"。"]],note:["多出的二十四爻，要从八卦的卦画中去寻求；画成纯卦（上下相叠）就是重叠之数，这就是闰数。（**本章接着第二十九章往下走**：第二十九章说「384 与含闰阴历年吻合」（外部印证），本章说「这多出来的 24 爻从哪里来」（内部推导）。**两章合读：外与内同时指向 384，才不是附会。**）"]},{id:"z30-02",label:"二、二十四为余",showLabel:!0,sentences:[["一岁三百六十，而爻数三百八十四，则是二十四爻为余也。以卦画求之，是为叠数。"]],note:["一年三百六十天，而爻数有三百八十四，那么多出来的二十四爻就是余数；从卦画来寻求，这是重叠之数。（**384 − 360 = 24**：麻衣把 360 爻定为「正爻」（配平年），把 24 爻定为「叠数」（配闰月）。**问题随之而来：这 24 爻，从卦画的哪个地方来？**）"]},{id:"z30-03",label:"三、八卦合体",showLabel:!0,sentences:[["何以言之？夫既有八卦矣。及八卦互相合体，以立诸卦。则诸卦者，八卦在其中矣。"]],note:["为什么这样说？已经有了八卦，八卦互相合体，组成各卦（六十四卦）；那么各卦之中，八卦都已经在其中了。（**这一句是为「叠」作准备**：56 个非纯卦里，上下卦各不相同，八卦各出现一次，**没有重复**——所以这 56 卦的爻数是「正常」的部分。）"]},{id:"z30-04",label:"四、八纯卦之叠",showLabel:!0,sentences:[["而别又有",{text:"八纯卦",glossary:"baChungua"},"，则其合体八卦为",{text:"重复",glossary:"chongfu"},"，而二十四数为叠也。"]],note:["而另外又有八个纯卦（上下卦相同），那么这八个纯卦的合体就是重复，二十四爻就是重叠之数。（**八纯卦就是乾、坤、坎、离、震、艮、巽、兑这八卦的重卦**——它们上下相叠，其中有一组三爻是「重复」出来的，**8 × 3＝24，正是那个余数。** 已在 56 个非纯卦中出现过的八卦，在这里又叠了一次。）"]},{id:"z30-05",label:"五、正爻与闰数",showLabel:!0,sentences:[["是以三百六十为正爻，与每岁之数合。而三百八十四，与闰岁之数合矣，则是闰数也。"]],note:["因此三百六十爻是正爻，与每岁（平年）的天数相合；而三百八十四爻，与闰年的天数相合——这就是闰数。（**关系很清楚**：正爻（360）＝平年＝常规运行；叠爻（24）＝闰月＝盈余积累；**合计（384）＝闰年＝完整周期。**）"]},{id:"z30-06",label:"六、见于数与象",showLabel:!0,sentences:[["岂惟见于数，亦见于象。人知之",{text:"该鲜",glossary:"gaiXian"},"矣。"]],note:["这个道理不只见于数，也见于象。知道这个道理的人，大概很少了。（**见于数**：384 − 360 = 24，8 纯卦 × 3 叠爻 = 24。**见于象**：八纯卦在象上就是「上下相同＝相叠」的样子，而闰月正是「正常年份之外叠加出来的时间」——**两者在象上都是「叠」。** 麻衣在此点到为止，未及展开。）"]}],o=[{id:"die",term:"叠",pinyin:"dié",meaning:"重叠。八纯卦上下卦相同，爻数重复，多出 24 爻，故为叠数。"},{id:"runshu",term:"闰数",pinyin:"rùn shù",meaning:"对应闰月的数。384 − 360 = 24，这 24 爻正是闰月的象数来源。"},{id:"baChungua",term:"八纯卦",pinyin:"bā chún guà",meaning:"上下卦相同的八卦：乾、坤、坎、离、震、艮、巽、兑（重卦）。"},{id:"chongfu",term:"重复",pinyin:"chóng fù",meaning:"重复出现。八纯卦的上下卦与原八卦重复。"},{id:"gaiXian",term:"该鲜",pinyin:"gāi xiǎn",meaning:"大概很少。「该」大约、大概，「鲜」少。"}];return(b,n)=>{const r=s("DaoTextReading"),l=s("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=t(`<h1 id="正易心法·第三十章" tabindex="-1">正易心法·第三十章 <a class="header-anchor" href="#正易心法·第三十章" aria-label="Permalink to &quot;正易心法·第三十章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章的核心命题：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>384 爻 = 360 正爻 + 24 叠爻</span></span>
<span class="line"><span>360 正爻 = 平年天数（常规）</span></span>
<span class="line"><span>24 叠爻  = 闰月天数（余数）</span></span>
<span class="line"><span>= 八纯卦的「叠」，对应历法的「闰」</span></span></code></pre></div><p><strong>论证路径</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 384 − 360 = 24（数的余量）</span></span>
<span class="line"><span>② 八卦互相合体立诸卦（56 卦，无重复）</span></span>
<span class="line"><span>③ 别又有八纯卦，上下相叠（重复）</span></span>
<span class="line"><span>④ 8 纯卦 × 3 叠爻 = 24（叠的数量）</span></span>
<span class="line"><span>⑤ 24 叠爻 = 闰月（天文对应）</span></span></code></pre></div><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>「叠」的逻辑</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>普通六爻卦（上下卦不同，56 卦）：</span></span>
<span class="line"><span>  上卦 ≠ 下卦 = 新的信息，无重复</span></span>
<span class="line"><span></span></span>
<span class="line"><span>八纯卦（上下卦相同，8 卦）：</span></span>
<span class="line"><span>  上卦 = 下卦 = 同一个三爻卦叠加自身 = 重复</span></span>
<span class="line"><span></span></span>
<span class="line"><span>叠的数量：</span></span>
<span class="line"><span>  每个纯卦有一个「三爻组」是叠出来的</span></span>
<span class="line"><span>  8 纯卦 × 3 爻 = 24 爻 = 叠数</span></span></code></pre></div><p><strong>「叠」在汉语中的功能</strong>：叠字（如「重重」「渐渐」）表示<strong>强调、延续、加深</strong>——<strong>这正是纯卦的象义</strong>：乾上乾下＝天行健，自强不息（持续）；坎上坎下＝习坎（反复练习）。<strong>纯卦在象上就是「叠」的象。</strong></p><p><strong>「岂惟见于数，亦见于象」</strong>：</p><table tabindex="0"><thead><tr><th></th><th>表现</th></tr></thead><tbody><tr><td><strong>见于数</strong></td><td>384 − 360 = 24；8 纯卦 × 3 叠爻 = 24</td></tr><tr><td><strong>见于象</strong></td><td>八纯卦「上下相同＝相叠」；闰月「正常年份之外叠加出来的时间」</td></tr></tbody></table><p><strong>两者在象上都是「叠」。</strong></p><p><strong>与第二十九章的关系</strong>：</p><table tabindex="0"><thead><tr><th>章</th><th>方向</th><th>内容</th></tr></thead><tbody><tr><td>第二十九章</td><td><strong>由外向内</strong></td><td>从天文（闰月）印证 384</td></tr><tr><td>第三十章</td><td><strong>由内向外</strong></td><td>从卦画内部（八纯卦）推导 24</td></tr></tbody></table><p><strong>双向验证</strong>：<strong>真正的「象之自然」，不需要从外部强行配合，卦画内部自己就能推导出来；推导出来的数，又与天文自然吻合。内外一致，才是「无余欠」「无容心」的自然之理。</strong></p><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先算三件事：<strong>384−360＝24；64−8＝56；8×3＝24</strong>；</li><li>再看「叠」字的双重含义：<strong>数上重复，象上相叠</strong>；</li><li>最后读「人知之该鲜矣」——<strong>麻衣在这里点到为止。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>二十四爻为余</strong>：384−360=24。</li><li><strong>叠数</strong>：从卦画求之。</li><li><strong>八卦合体</strong>：56 卦中八卦各在其中（无重复）。</li><li><strong>八纯卦</strong>：上下相同，故为重复。</li><li><strong>正爻与闰数</strong>：360 配平年，384 配闰年。</li><li><strong>见于数与象</strong>：数与象同指一个「叠」。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,21)),e(r,{colophon:"二十四爻 · 画纯为叠 · 正爻与闰数 · 见于数与象",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第三十章原文",sections:i,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本，不作统一。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(l,{items:[{term:"叠数",pinyin:["dié","shù"],meaning:"八纯卦上下卦相同，爻数重复，多出的 24 爻即叠数——384 − 360 = 24。"},{term:"八纯卦",pinyin:["bā","chún"],meaning:"上下卦相同的八卦：乾、坤、坎、离、震、艮、巽、兑。每个纯卦有 3 爻是「叠」出来的。"},{term:"正爻与闰数",pinyin:["zhèng","yáo"],meaning:"360 为正爻（配平年），384 与闰年之数合——24 叠爻即闰月的象数来源。"},{term:"叠（象）",pinyin:["dié"],meaning:"纯卦在象上是「上下相叠」，闰月在时间上是「叠加出来的一个月」，两者同为一个「叠」。"},{term:"该鲜",pinyin:["gāi","xiǎn"],meaning:"大概很少。「该」大约，「鲜」少。麻衣在此点到为止，未及展开「见于象」的部分。"}]}),n[3]||(n[3]=t(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章的核心命题：<strong>384 爻＝360 正爻＋24 叠爻；360 配平年，24 配闰月；其数来自八纯卦上下相叠之重复。</strong></p><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>为什么八纯卦是「叠」？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>普通卦（上下不同）：两个不同的三爻卦组合 = 新的信息，无重复</span></span>
<span class="line"><span>纯卦（上下相同）：同一个三爻卦叠加自身 = 重复</span></span>
<span class="line"><span></span></span>
<span class="line"><span>叠的数量：8 纯卦 × 3 叠爻 = 24 爻</span></span></code></pre></div><p><strong>「岂惟见于数，亦见于象」</strong>：</p><table tabindex="0"><thead><tr><th></th><th>表现</th></tr></thead><tbody><tr><td>见于数</td><td>384 − 360 = 24；8 × 3 = 24</td></tr><tr><td>见于象</td><td>八纯卦「上下相同＝相叠」；闰月「正常年份之外叠加出来的时间」</td></tr></tbody></table><p><strong>与第二十九章的双向验证</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第二十九章：由外向内（从天文印证 384）</span></span>
<span class="line"><span>第三十章：  由内向外（从卦画推导 24）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>真正的「象之自然」：</span></span>
<span class="line"><span>  卦画内部自己就能推导出来，推导出来的数又与天文自然吻合</span></span>
<span class="line"><span>  内外一致，才是「无余欠」「无容心」的自然之理</span></span></code></pre></div><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>算三件事：<strong>384−360＝24、64−8＝56、8×3＝24</strong>；</li><li>看「叠」字的双重含义：<strong>数上重复，象上相叠</strong>；</li><li>顺着钩子想（承接昇哥的问题）：<strong>麻衣说「亦见于象」，但没展开——是留白，还是论证的缺口？</strong> 我的看法：<strong>两者都可能，而读者最诚实的态度是「追问它」。</strong> 我来试着补上：<strong>「叠」在象上就是「上下相同」；闰在历法上就是「同一年多出来的一个月」——两者都是「同一个东西在自身之上再加一次」。</strong> 这个补充未必是麻衣的意思，但它是<strong>按他的逻辑往下走的</strong>：<strong>不是替他说完，是把他的「留白」当成一个入口。</strong> 这也正是这本书希望读者做的事。</li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>多出的二十四爻，要从八卦的卦画中去寻求；画成纯卦（上下相叠）就是重叠之数，这就是闰数。</p><p>一年三百六十天，而爻数有三百八十四，那么多出来的二十四爻就是余数；从卦画来寻求，这是重叠之数。</p><p>为什么这样说？已经有了八卦，八卦互相合体，组成各卦；那么各卦之中，八卦都已经在其中了。</p><p>而另外又有八个纯卦（上下卦相同），那么这八个纯卦的合体就是重复，二十四爻就是重叠之数。</p><p>因此三百六十爻是正爻，与每岁（平年）的天数相合；而三百八十四爻，与闰年的天数相合——这就是闰数。</p><p>这个道理不只见于数，也见于象。知道这个道理的人，大概很少了。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第三十章回答了第二十九章留下的问题——<strong>那多出来的 24 爻不是零头，是八纯卦「叠」出来的闰月。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「384 − 360 = 24」</strong>——这个减法看起来简单，但<strong>麻衣把它变成了一个有内容的差</strong>：不是「多了一点」，是「多了闰月」。</li><li><strong>「叠」的三个层次</strong>——数上：8 纯卦 × 3 爻 = 24；象上：上下卦相同＝相叠；历法上：闰月＝叠加出来的一个月。<strong>三次都是同一个字，这是麻衣最喜欢的手法：一个字打通三个系统。</strong></li><li><strong>「纯卦在象上就是叠」</strong>——这一点很妙：<strong>乾上乾下＝天行健，自强不息；坎上坎下＝习坎，反复练习。</strong> 汉语的叠字（重重、渐渐）本来就有「强调、延续」的功能——<strong>卦名本身就在说「叠」。</strong></li><li><strong>「内外双证」</strong>——第二十九章从天文往卦画走，本章从卦画往天文走。<strong>两条路走到一处，才叫「象之自然」。</strong> 这也解释了麻衣为什么反复批汉儒「附会」：<strong>附会是单向的（先定结论再凑），自然之理是双向的。</strong></li><li><strong>「人知之该鲜矣」</strong>——麻衣在这里点到为止。<strong>他说「亦见于象」，但没展开。</strong></li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>「点到为止」是智慧的留白，还是论证的缺口？</strong> 我的看法：<strong>两者从外部看几乎无法区分</strong>，所以最诚实的态度是<strong>追问它</strong>——我来试着补上：「叠」在象上是「上下相同」，闰在历法上是「一年里多出来的一个月」；<strong>两者都是「同一个东西在自身之上再加一次」。</strong> 这个补充未必是麻衣的意思，<strong>但它是我按他的逻辑往下走的——不是替他说完，是把他的留白当成一个入口。</strong></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-28">第二十八章 · 乾坤六子</a> — 象数双证之法（本章同法）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-29">第二十九章 · 以闰求之</a> — 由外向内印证 384（本章由内向外推导 24）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-31">第三十一章</a> — 八宫八变与一年之数</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-36">第三十六章</a> — 策数六八（48＝8×6，本章的续论）</li></ul>`,25))])}}});export{y as __pageData,x as default};
